				    (error = is_valid_repository_path(&is_valid, &repo_link, &common_link, flags)) < 0)
					goto out;

				if (is_valid) {
					git_str_swap(&out->gitdir, &repo_link);

					if ((error = git_str_put(&out->gitlink, path.ptr, path.size)) < 0)
						goto out;

					git_str_swap(&common_link, &out->commondir);
				}
				break;
			}
